ALTER TABLE public.matches ADD COLUMN accepted_at timestamptz,ADD COLUMN review_status text NOT NULL DEFAULT 'pendente',ADD COLUMN registration_link text;
CREATE OR REPLACE FUNCTION public.generate_job_matches(_job uuid) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE j public.jobs; rec record; n integer:=0; skills text[]; matched text[]; score_value integer; BEGIN SELECT * INTO j FROM public.jobs WHERE id=_job; IF NOT FOUND OR NOT public.organization_permission(j.company_id,'empresa',CASE WHEN j.job_type='interna' THEN 'vagas_internas' ELSE 'vagas_externas' END,j.scope_id) THEN RAISE EXCEPTION 'Acesso negado'; END IF; FOR rec IN SELECT lp.user_id,lp.profile_role FROM public.learner_profiles lp WHERE (j.job_type='externa' AND lp.profile_role IN('estudante','geral') AND lp.matching_enabled) OR (j.job_type='interna' AND lp.profile_role='colaborador' AND EXISTS(SELECT 1 FROM public.company_employees e WHERE e.user_id=lp.user_id AND e.company_id=j.company_id AND e.ended_at IS NULL AND (j.scope_id IS NULL OR e.scope_id=j.scope_id))) LOOP SELECT COALESCE(array_agg(DISTINCT s.name),'{}') INTO skills FROM public.certificates c JOIN public.course_skills cs ON cs.course_id=c.course_id JOIN public.skills s ON s.id=cs.skill_id WHERE c.user_id=rec.user_id AND c.profile_role=rec.profile_role; SELECT COALESCE(array_agg(x),'{}') INTO matched FROM unnest(j.required_skills||j.desired_skills) x WHERE lower(x)=ANY(ARRAY(SELECT lower(y) FROM unnest(skills) y)); score_value:=CASE WHEN cardinality(j.required_skills||j.desired_skills)=0 THEN 35 ELSE least(99,round(99.0*cardinality(matched)/cardinality(j.required_skills||j.desired_skills))) END; IF NOT EXISTS(SELECT 1 FROM public.matches WHERE job_id=_job AND user_id=rec.user_id AND profile_role=rec.profile_role) THEN INSERT INTO public.matches(user_id,job_id,profile_role,score,matched_skills,reasons) VALUES(rec.user_id,_job,rec.profile_role,score_value,matched,ARRAY[CASE WHEN cardinality(matched)>0 THEN 'Competências compatíveis: '||array_to_string(matched,', ') ELSE 'Compatibilidade parcial; avalie os requisitos antes de decidir' END]); INSERT INTO public.notifications(user_id,profile_role,title,body) VALUES(rec.user_id,rec.profile_role,'Nova oportunidade sugerida',j.title||' — confira os requisitos e decida se deseja se candidatar.'); n:=n+1; END IF; END LOOP; INSERT INTO public.activity_logs(user_id,organization_id,organization_type,scope_id,action,entity,meta) VALUES(auth.uid(),j.company_id,'empresa',j.scope_id,'matching_gerado','jobs',jsonb_build_object('job_id',_job,'count',n)); RETURN n; END $$;
CREATE OR REPLACE FUNCTION public.respond_match(_match uuid,_accept boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE m public.matches; j public.jobs; BEGIN SELECT * INTO m FROM public.matches WHERE id=_match AND user_id=auth.uid() AND profile_role=public.current_profile_role() FOR UPDATE; SELECT * INTO j FROM public.jobs WHERE id=m.job_id; IF m.id IS NULL OR j.status<>'aberta' OR m.status<>'sugerida' THEN RAISE EXCEPTION 'Sugestão indisponível'; END IF; IF m.profile_role IN('estudante','geral') AND NOT EXISTS(SELECT 1 FROM public.learner_profiles WHERE user_id=auth.uid() AND profile_role=m.profile_role AND matching_enabled) THEN RAISE EXCEPTION 'Matching desativado'; END IF; IF m.profile_role='colaborador' AND (j.job_type<>'interna' OR NOT EXISTS(SELECT 1 FROM public.company_employees WHERE user_id=auth.uid() AND company_id=j.company_id AND ended_at IS NULL)) THEN RAISE EXCEPTION 'Vaga fora da organização'; END IF; UPDATE public.matches SET status=CASE WHEN _accept THEN 'aceita'::public.match_status ELSE 'ignorada'::public.match_status END,accepted_at=CASE WHEN _accept THEN now() END WHERE id=_match; END $$;
CREATE OR REPLACE FUNCTION public.company_update_match(_match uuid,_status text,_link text DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE m public.matches; j public.jobs; BEGIN SELECT * INTO m FROM public.matches WHERE id=_match; SELECT * INTO j FROM public.jobs WHERE id=m.job_id; IF m.status<>'aceita' OR NOT public.organization_permission(j.company_id,'empresa','candidatos',j.scope_id) OR _status NOT IN('pendente','em_avaliacao','finalizada') OR (_link IS NOT NULL AND _link !~ '^https://') THEN RAISE EXCEPTION 'Candidatura não autorizada'; END IF; UPDATE public.matches SET review_status=_status,registration_link=_link WHERE id=_match; IF _link IS NOT NULL THEN INSERT INTO public.notifications(user_id,profile_role,title,body) VALUES(m.user_id,m.profile_role,'Cadastro solicitado pela empresa',_link); END IF; INSERT INTO public.activity_logs(user_id,organization_id,organization_type,scope_id,action,entity,meta) VALUES(auth.uid(),j.company_id,'empresa',j.scope_id,'candidatura_atualizada','matches',jsonb_build_object('match_id',_match)); END $$;
CREATE POLICY matches_server_write_guard ON public.matches AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK(false);
CREATE POLICY matches_server_update_guard ON public.matches AS RESTRICTIVE FOR UPDATE TO authenticated USING(false) WITH CHECK(false);
REVOKE ALL ON FUNCTION public.generate_job_matches(uuid),public.respond_match(uuid,boolean),public.company_update_match(uuid,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.generate_job_matches(uuid),public.respond_match(uuid,boolean),public.company_update_match(uuid,text,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.audit_organization_job() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NOT NULL THEN INSERT INTO public.activity_logs(user_id,organization_id,organization_type,scope_id,action,entity,meta) VALUES(auth.uid(),NEW.company_id,'empresa',NEW.scope_id,'vaga_'||lower(TG_OP),'jobs',jsonb_build_object('job_id',NEW.id)); END IF; RETURN NEW; END $$;
CREATE TRIGGER jobs_organization_audit AFTER INSERT OR UPDATE ON public.jobs FOR EACH ROW EXECUTE FUNCTION public.audit_organization_job();